value.markdown:
### Section Visibility

The `isAvailable` function on a SectionAxiom controls whether the **entire section** is rendered. The function's parameter names tell FOAM which properties to watch; the section re-evaluates automatically when those properties change.

```javascript
sections: [
  {
    name: 'billingAddress',
    title: 'Billing Address',
    isAvailable: function(contactType) {
      return contactType === 'BUSINESS';
    }
  }
]
```

When `isAvailable` returns `false`, the section card is **completely removed** from the DOM — no whitespace is left behind.

#### Section Permissioning

Set `permissionRequired: true` on a section to hide it when the user lacks the corresponding auth permission. This check is evaluated in addition to `isAvailable`. The permission string is formatted as 

```
<class.id.toLowerCase()>.section.<sectionName>
```

value.code:
// DemoVisibility has 2 sections:
// 'Always Visible' is always shown
// 'Business Only' appears only when contactType === 'BUSINESS'
foam.CLASS({
  package: 'foam.u2.demos',
  name: 'DemoVisibility',

  sections: [
    { name: 'always',      title: 'Always Visible', order: 1 },
    {
      name: 'conditional',
      title: 'Business Only',
      order: 2,
      isAvailable: function(contactType) { return contactType === 'BUSINESS'; }
    }
  ],

  properties: [
    {
      class: 'String',
      name: 'contactType',
      label: 'Type',
      section: 'always',
      view: {
        class: 'foam.u2.view.ChoiceView',
        choices: [['PERSONAL', 'Personal'], ['BUSINESS', 'Business']]
      }
    },
    { class: 'String', name: 'orgName', label: 'Organization', section: 'conditional' }
  ]
});

// Switch the dropdown from Personal -> Business to reveal the hidden section
var instance = foam.u2.demos.DemoVisibility.create({ contactType: 'PERSONAL' });
start().startContext({ data: instance })
  .tag({ class: 'foam.u2.detail.SectionedDetailView', data: instance })
.endContext().end();

value.markdown:
### Customizing <Some>DetailViews

#### useSections

Render only a specific subset of sections, in a given order:

```javascript
tag({
  class: 'foam.u2.detail.SectionedDetailView',
  data: myContact,
  useSections: ['identity', 'preferences']  // skips contactInfo
})
```

#### propertyWhitelist

A map of `{ propertyName: { ...overrides } }`. When provided:
- Only whitelisted properties are shown across all sections
- Each entry can override any property attribute (`gridColumns`, `label`, etc.)
- Sections with no visible properties after filtering are hidden automatically

```javascript
tag({
  class: 'foam.u2.detail.VerticalDetailView',
  data: myInstance,
  propertyWhitelist: {
    'name':  { gridColumns: 12 },
    'email': { label: 'Work Email' }
  }
})
```

Both options can be combined: `useSections` picks which sections appear; `propertyWhitelist` further filters properties within those sections.

value.code:
var DC = foam.u2.demos.DemoContact;
var contact = DC.create({
  name: 'Jane Doe',
  email: 'jane@example.com',
  contactType: 'BUSINESS',
  organization: 'Acme Corp',
  age: 32,
  active: true
});
start('div').style({ display: 'flex', gap: '2rem' })
  .start('div').style({ flex: 1 })
    .start('p').addClass('p-label').add('useSections: identity + preferences only').end()
      .tag({
        class: 'foam.u2.detail.SectionedDetailView',
        data: contact,
        useSections: ['identity', 'preferences']
      })
  .end()
  .start('div').style({ flex: 1 })
    .start('p').addClass('p-label').add('propertyWhitelist: name and email only').end()
      .tag({
        class: 'foam.u2.detail.VerticalDetailView',
        data: contact,
        propertyWhitelist: {
          'name':  { gridColumns: 12 },
          'email': { gridColumns: 12, label: 'Work Email' },
          'phone': {} // no overrides
        }
      })
  .end()
.end();

value.markdown:
### Reactive Section Titles and Subtitles

Section `title` and `subTitle` can be strings or **functions** that receive the model instance's property values as arguments. FOAM infers which properties to watch from the **parameter names**. The title re-renders automatically when those properties change.

```javascript
sections: [
  {
    name: 'identity',
    title: function(name) {
      return name ? 'Profile — ' + name : 'Profile';
    },
    subTitle: 'Edit contact details'
  }
]
```

#### subTitle

`subTitle` works the same way and appears in a lighter style below the title.

Both `title` and `subTitle` also support **template literal** strings with `${propName}` — FOAM evaluates these against the live data automatically.

value.code:
// DemoReactiveTitle has a section whose title maps over the 'name' property.
foam.CLASS({
  package: 'foam.u2.demos',
  name: 'DemoReactiveTitle',

  sections: [
    {
      name: 'main',
      order: 1,
      title: function(name) { return name ? 'Profile — ' + name : 'Profile'; },
      subTitle: 'Edit your contact details'
    }
  ],

  properties: [
    { class: 'String', name: 'name',  label: 'Full Name', section: 'main', gridColumns: 6, onKey: true },
    { class: 'String', name: 'email', label: 'Email',     section: 'main', gridColumns: 6 }
  ]
});

// Edit the Full Name field and watch the section title update live.
var instance = foam.u2.demos.DemoReactiveTitle.create({ name: 'Jane Doe', email: 'jane@example.com' });
start()
  .tag({ class: 'foam.u2.detail.SectionedDetailView', data: instance })
.end();

// DemoCollapsible has two sections:
// 'Basic Info' is always visible
// 'Advanced' is collapsable and has help text — click the chevron to collapse it

foam.CLASS({
  package: 'foam.u2.demos',
  name: 'DemoCollapsible',

  sections: [
    { name: 'basic',    title: 'Basic Info', order: 1 },
    {
      name: 'advanced',
      title: 'Advanced',
      order: 2,
      collapsable: true,
      help: 'These settings are optional'
    }
  ],

  properties: [
    { class: 'String', name: 'name',  label: 'Name',  section: 'basic',    gridColumns: 6 },
    { class: 'String', name: 'email', label: 'Email', section: 'basic',    gridColumns: 6 },
    { class: 'String', name: 'notes', label: 'Notes', section: 'advanced', gridColumns: 12 },
    { class: 'Int',    name: 'age',   label: 'Age',   section: 'advanced', gridColumns: 4 }
  ]
});

var instance = foam.u2.demos.DemoCollapsible.create({
  name: 'Jane Doe',
  email: 'jane@example.com',
  age: 32,
  notes: 'Prefers email contact.'
});
start()
  .tag({ class: 'foam.u2.detail.VerticalDetailView', data: instance })
.end();

var DC = foam.u2.demos.DemoContact;
var contact = DC.create({
  name: 'Jane Doe',
  contactType: 'BUSINESS',
  organization: 'Acme Corp'
});
// Render only the 'identity' section directly via SectionView
start().startContext({ controllerMode: 'VIEW' })
  .tag({
    class: 'foam.u2.detail.TabularSectionView',
    data: contact,
    of: DC,
    sectionName: 'identity',
    showTitle: true
  })
.endContext().end();

/* 
Note that the section for contact details specifies its own properties.
These properties can belong to another section without conflicting.
It is the responsibility of the user configuring the view to make sure 
the properties are visible only once
*/
foam.CLASS({
  package: 'foam.u2.demos',
  name: 'DemoOverloading',

  sections: [
    { name: 'basic',    title: 'Basic Info' },
    {
      name: 'contactDetails',
      properties: [
        // You can use propName if you dont need overrides
        'email', 
        // Or use a map if you need overrides
        { name: 'phone', label: '####', supportingLabel: 'This label is different from the one in the other section' },
        // Or use a nested property on an FObjectProperty
        { name: 'address.city' }
      ]
    }
  ],

  properties: [
    { class: 'String', name: 'name',  section: 'basic',    gridColumns: 6 },
    { class: 'String', name: 'email', section: 'basic',    gridColumns: 6 },
    { class: 'PhoneNumber', name: 'phone', section: 'basic',    gridColumns: 6 },
    { class: 'Int',    name: 'age',   section: 'basic', gridColumns: 4 },
    {
      class: 'FObjectProperty',
      of: 'foam.u2.demos.DemoAddress',
      name: 'address',
      section: 'basic',
      gridColumns: 12,
      factory: function() { return foam.u2.demos.DemoAddress.create({ city: 'Toronto' }) }
    }
  ]
});

var instance = foam.u2.demos.DemoOverloading.create({
  name: 'Jane Doe',
  email: 'jane@example.com',
  age: 32,
  phone: '123456'
});
start()
  .tag({ class: 'foam.u2.detail.SectionedDetailView', data: instance })
.end();

/* 
foam.u2.demos.DemoContact has the following properties that already belong to 
different sections: 
- name: identity section
- email: contactInfo section
- active: preferences section

It is reasonable to expect a management screen to maybe show these three properties in a section so that a user can manage contacts at a glance.
*/
var instance = foam.u2.demos.DemoContact.create({
  name: 'John Doe',
  email: 'john@example.com',
  age: 32,
  phone: '123456'
});
start()
  .tag({
      class: 'foam.u2.detail.SectionedDetailView',
      // When defining your own sections, `of` must be provided
      of: 'foam.u2.demos.DemoContact',
      data: instance,
      sections: [
         /* 
         Define your own set of sections that are only used for this view
         This is the same sectionAxiom that we define on models so all the same
         features are available here
        */
        {
          name: 'myCustomManagementSection_',
          properties: ['name', 'email', 'active'],
          title: function(name) { return 'Manage Contact - ' + name; }
        }    
      ]
  }).end();

// SIN 1 - heap: retain a large allocation so heap-delta flags and this block tops +Heap.
globalThis.__perfDemoBallast__ = [];
for ( var i = 0 ; i < 1200000 ; i++ ) globalThis.__perfDemoBallast__.push({ i: i, s: 'ballast-' + i });
log('retained ' + globalThis.__perfDemoBallast__.length + ' objects');

// SIN 2 - CPU: one long synchronous task so longest-task / main-thread-blocked flag and this block tops Time.
var deadline = performance.now() + 300;
var z = 0; while ( performance.now() < deadline ) z += Math.sqrt(z + 1);
log('busy result ' + Math.round(z));

// SIN 3 - DOM: build thousands of hidden nodes so DOM-nodes-added flags and this block tops +DOM.
for ( var r = 0 ; r < 12000 ; r++ ) this.out.start('span').style({ display: 'none' }).add('cell ' + r).end();
log('built 12000 hidden nodes');

// SIN 4 - console noise: spam warnings so the warn-rate metric flags (each warn also costs a stack capture).
for ( var i = 0 ; i < 400 ; i++ ) console.warn('perfBadWorkload demo warning ' + i);
log('emitted 400 warnings');

// SIN 5 - repeated + varied server queries: POST region selects with predicates so the
// Service-calls expand shows identical re-fetches (3x the SAME predicate = cacheable) next to
// DISTINCT queries (different predicates). Posts directly because regionDAO is a client
// CachingDAO - where(pred).select() would fill the cache once and filter locally, never
// sending the predicate to the server.
var R = foam.core.auth.Region;
var E = foam.mlang.Expressions.create();
function body(pred) {
  var msg = foam.box.RPCMessage.create({ name: 'select_', args: [ null, foam.dao.ArraySink.create(), 0, 1000, null, pred ] });
  return foam.json.Network.stringify(foam.box.Envelope.create({ message: msg }));
}
async function hit(pred) { try { await fetch('/service/regionDAO', { method: 'POST', body: body(pred) }); } catch (e) {} }
if ( R ) {
  for ( var i = 0 ; i < 3 ; i++ ) await hit(E.EQ(R.COUNTRY_ID, 'US'));
  await hit(E.EQ(R.COUNTRY_ID, 'FR'));
  await hit(E.EQ(R.COUNTRY_ID, 'IT'));
  log('posted region selects: 3x countryId=US (identical), 1x FR, 1x IT (distinct)');
} else {
  log('Region model unavailable');
}

// Auto-run loadPerf on the bad workload once this launcher has finished loading,
// so the load happens outside this flow's own load (no nested load).
var shell = globalThis.shell;
if ( shell && shell.value && shell.value.loadComplete ) {
  shell.value.loadComplete.sub(foam.events.oneTime(function() {
    shell.eval_('loadPerf("perfBadWorkload")');
  }));
  log('Launching perf capture on perfBadWorkload...');
} else {
  log('Console shell unavailable - run loadPerf("perfBadWorkload") manually.');
}
